export class Temporizador {
  constructor(segundos, elemento) {
    this.segundos = segundos;
    this.elemento = elemento;
    this.intervalo = null;
  }

  iniciar() {
    this.intervalo = setInterval(function () {
      this.segundos--;
      this.pintar();
      if (this.segundos === 0) {
        clearInterval(this.intervalo);
      }
    }, 1000);
  }

  pausar() {
    clearInterval(this.intervalo);
  }

  pintar() {
    const min = Math.floor(this.segundos / 60);
    const seg = this.segundos % 60;
    this.elemento.textContent = `${min}:${seg}`;
  }
}

